    $id = request()->segment(4);
    $user = \Auth()->user();
    $data = App\Models\NVMaterial::where('nv_id', $id)->first();
    
    $Nvsericestatus = App\Models\Nvsericestatus::where('material_id', $data->id)->exists();
    
    if ($Nvsericestatus) {
        $Nvsericestatus = App\Models\Nvsericestatus::where('material_id', $data->id)->first();
    } else {
        $Nvsericestatus = App\Models\Nvsericestatus::where('service_id', $data->id)->first();
    }
    $employees_data = App\Models\Employee::where('user_id', $user->id)->first();
    $department = App\Models\Department::where('id', $employees_data->department_id)->first();
    $hod = $department->dep_hod;
    $rv1 = $department->dep_rew1;
    $rv2 = $department->dep_rew2;
    $rv3 = $department->dep_rew3;
    $rv4 = $department->dep_rew4;
    
    $id0 = App\Models\Workflow::where('id', 1)->first();
    $id1 = App\Models\Workflow::skip(1)->first();
    $id2 = App\Models\Workflow::skip(2)->first();
    $id3 = App\Models\Workflow::skip(3)->first();
    $id4 = App\Models\Workflow::skip(4)->first();
    $id5 = App\Models\Workflow::skip(5)->first();
    
